/**
 * RawEvidenceExplorer - 原始 JSON 证据浏览器
 * 支持对原始上传文件进行路径搜索和结构探索
 *
 * 性能策略：
 * - 默认在 Worker 中执行深度搜索，避免主线程递归扫描大 JSON
 * - Worker 不可用或失败时降级到主线程搜索（仍限制 maxResults/maxDepth）
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { Card, Input, Button, Tag, Tooltip, message, Modal, Space } from 'antd';
import {
  SearchOutlined,
  CopyOutlined,
  FileSearchOutlined,
  FullscreenOutlined,
  SwapOutlined,
} from '@ant-design/icons';
import { JsonPathMatch, StructureNode } from '../../parsers/shared/rawJsonPath';
import { copyText } from '../../utils/copyText';
import {
  loadRawEvidenceStructure,
  readRawEvidenceValuePreview,
  searchRawEvidence,
} from './rawEvidenceGateway';
import { useNavigation } from '../../contexts/NavigationContext';
import {
  RAW_EVIDENCE_VALUE_PREVIEW_MAX_CHARS,
  SEARCH_DEBOUNCE_MS,
} from '../../constants/analysisThresholds';
import EmptyState from '../shared/EmptyState';

interface RawEvidenceExplorerProps {
  /** 原始 JSON 数据（上传的文件内容） */
  rawData?: unknown;
  /**
   * rawData 在 Worker 内的缓存 ID
   * 有该值时，搜索必须走 `rawDataId`（避免 structured clone 大 JSON）
   */
  rawDataId?: string;
  /** 文件名 */
  fileName?: string;
}

const RawEvidenceExplorer: React.FC<RawEvidenceExplorerProps> = ({ rawData, rawDataId, fileName }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<JsonPathMatch[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [expandedValue, setExpandedValue] = useState<string | null>(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [wrapPreview, setWrapPreview] = useState(true);
  const [workerStructure, setWorkerStructure] = useState<StructureNode[]>([]);
  const searchTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const searchTaskIdRef = useRef(0);
  const valueTaskIdRef = useRef(0);
  const pendingSelectPathRef = useRef<string | null>(null);
  const { intent, consumeIntent } = useNavigation();

  useEffect(() => {
    return () => {
      if (searchTimer.current) clearTimeout(searchTimer.current);
    };
  }, []);

  const structure = workerStructure;

  useEffect(() => {
    let cancelled = false;
    if (!rawData && !rawDataId) {
      setWorkerStructure([]);
      return;
    }

    loadRawEvidenceStructure({ rawData, rawDataId })
      .then(result => {
        if (cancelled) return;
        setWorkerStructure(result.value);
        if (result.fallbackUsed) {
          message.warning('Worker 结构读取失败，已降级到主线程结构预览');
        }
      })
      .catch(() => {
        if (!cancelled) {
          setWorkerStructure([]);
          if (rawData) {
            message.warning('Worker 结构读取失败，已降级到主线程结构预览');
          } else {
            message.error('原始 JSON 结构读取失败，请重新上传文件');
          }
        }
      });

    return () => {
      cancelled = true;
    };
  }, [rawDataId, rawData]);

  const readValuePreview = useCallback(async (path: string): Promise<string> => {
    const result = await readRawEvidenceValuePreview({ rawData, rawDataId }, path);
    return result.value;
  }, [rawData, rawDataId]);

  const handleSearch = useCallback((query: string) => {
    const taskId = ++searchTaskIdRef.current;
    setSearchQuery(query);
    if (searchTimer.current) clearTimeout(searchTimer.current);

    if (!query.trim()) {
      setSearchResults([]);
      setIsSearching(false);
      return;
    }

    setIsSearching(true);
    searchTimer.current = setTimeout(() => {
      const q = query.trim();

      const run = async () => {
        try {
          const results = await searchRawEvidence({ rawData, rawDataId }, q);
          if (taskId !== searchTaskIdRef.current) return;
          setSearchResults(results.value);
          setIsSearching(false);
          if (results.fallbackUsed) {
            message.warning('Worker 搜索失败，已降级到主线程搜索（大文件可能卡顿）');
          }
        } catch (err) {
          if (taskId !== searchTaskIdRef.current) return;
          setSearchResults([]);
          setIsSearching(false);
          message.error(err instanceof Error ? err.message : '搜索失败');
        }
      };

      void run();
    }, SEARCH_DEBOUNCE_MS);
  }, [rawData, rawDataId]);

  // 消费导航意图：支持从诊断卡一键跳到 raw-evidence，并自动执行搜索
  useEffect(() => {
    if (!intent || intent.tab !== 'raw-evidence') return;
    const q = intent.filters?.paramField || intent.filters?.keyword || '';
    if (q) {
      pendingSelectPathRef.current = q;
      handleSearch(q);
    }
    consumeIntent();
  }, [intent, consumeIntent, handleSearch]);

  // 如果 intent 传入的是一个精确 fieldPath（如 $.log.entries[0].request.url），且搜索结果包含该 path，则自动选中
  useEffect(() => {
    const wanted = pendingSelectPathRef.current;
    if (!wanted) return;
    const hit = searchResults.find(r => r.path === wanted);
    if (!hit) return;
    pendingSelectPathRef.current = null;
    setSelectedPath(hit.path);
    const taskId = ++valueTaskIdRef.current;
    setExpandedValue('读取中...');
    void readValuePreview(hit.path)
      .then(value => {
        if (taskId !== valueTaskIdRef.current) return;
        setExpandedValue(value);
      })
      .catch(() => {
        if (taskId !== valueTaskIdRef.current) return;
        setExpandedValue(null);
        message.error('字段值读取失败');
      });
  }, [searchResults, readValuePreview]);

  const handleCopyPath = async (path: string) => {
    try {
      await copyText(path);
      message.success('路径已复制');
    } catch {
      message.error('复制失败');
    }
  };

  const handleCopyValue = async () => {
    try {
      await copyText(expandedValue || '');
      message.success('值已复制');
    } catch {
      message.error('复制失败');
    }
  };

  const handleSelectPath = (path: string) => {
    const taskId = ++valueTaskIdRef.current;
    setSelectedPath(path);
    setExpandedValue('读取中...');
    void readValuePreview(path)
      .then(value => {
        if (taskId !== valueTaskIdRef.current) return;
        setExpandedValue(value);
      })
      .catch(() => {
        if (taskId !== valueTaskIdRef.current) return;
        setExpandedValue(null);
        message.error('字段值读取失败');
      });
  };

  if (!rawData && !rawDataId) {
    return (
      <Card>
        <EmptyState title="暂无原始数据可浏览" description="上传 NetLog 或 HAR 后，可以在这里搜索和核对原始字段。" />
      </Card>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 18, padding: '18px 20px 24px' }}>
      <Card
        styles={{ body: { padding: 18 } }}
        style={{
          borderRadius: 16,
          borderColor: 'rgba(99, 102, 241, 0.18)',
          background: 'linear-gradient(180deg, rgba(99,102,241,0.07), var(--bg-elevated) 72px)',
          boxShadow: '0 10px 28px rgba(15,23,42,0.08)',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap', marginBottom: 14 }}>
          <div style={{ minWidth: 0 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap', fontSize: 16, fontWeight: 800, color: 'var(--text-primary)' }}>
              <FileSearchOutlined style={{ fontSize: 17, color: '#6366f1' }} />
              <span>原始证据浏览器</span>
            </div>
            <div style={{ marginTop: 6, fontSize: 12, color: 'var(--text-muted)', lineHeight: 1.7 }}>
              输入字段名或值进行搜索，例如 net_error、ERR_、dns、timeout。
            </div>
          </div>
          {fileName && <Tag style={{ margin: 0, borderRadius: 999 }}>{fileName}</Tag>}
        </div>
        <Input
          size="large"
          prefix={<SearchOutlined style={{ color: 'var(--text-muted)' }} />}
          placeholder="搜索字段名或值... (如: net_error, proxy, certificate, source_dependency)"
          value={searchQuery}
          onChange={e => handleSearch(e.target.value)}
          allowClear
          style={{
            borderRadius: 12,
            height: 42,
            background: 'var(--bg-surface)',
            boxShadow: 'inset 0 0 0 1px rgba(148,163,184,0.10)',
          }}
        />
      </Card>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'minmax(360px, 0.42fr) minmax(0, 0.58fr)',
          gap: 16,
          minHeight: 'calc(100vh - 260px)',
          overflow: 'hidden',
          padding: 12,
          borderRadius: 16,
          background: 'var(--bg-surface)',
          border: '1px solid var(--border-color)',
        }}
      >
        {/* Left: Results / Structure */}
        <Card
          size="small"
          title={searchQuery ? `搜索结果 (${searchResults.length})` : '文件结构'}
          styles={{ body: { padding: 8, height: 'calc(100vh - 330px)', minHeight: 480, overflow: 'auto' } }}
          style={{ borderRadius: 14, overflow: 'hidden', minWidth: 0 }}
        >
          {searchQuery ? (
            searchResults.length === 0 ? (
              <div style={{ padding: 24, textAlign: 'center', color: 'var(--text-muted)' }}>
                {isSearching ? '搜索中...' : '未找到匹配结果'}
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column' }}>
                {searchResults.map((match, i) => (
                  <PathResultItem
                    key={`${match.path}-${i}`}
                    match={match}
                    isSelected={selectedPath === match.path}
                    onClick={() => handleSelectPath(match.path)}
                    onCopyPath={() => handleCopyPath(match.path)}
                  />
                ))}
              </div>
            )
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              {structure.map((node, i) => (
                <StructureItem
                  key={`${node.path}-${i}`}
                  node={node}
                  onClick={() => handleSelectPath(node.path)}
                  isSelected={selectedPath === node.path}
                />
              ))}
            </div>
          )}
        </Card>

        {/* Right: Value Preview */}
        <Card
          size="small"
          title={
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <span>值预览</span>
              {selectedPath && (
                <Tag style={{ margin: 0, fontSize: 11, fontFamily: "'SF Mono', monospace" }}>
                  {selectedPath}
                </Tag>
              )}
            </div>
          }
          extra={expandedValue && (
            <Space size={6}>
              {selectedPath && (
                <Button size="small" icon={<CopyOutlined />} onClick={() => handleCopyPath(selectedPath)}>
                  复制路径
                </Button>
              )}
              <Button size="small" icon={<CopyOutlined />} onClick={handleCopyValue}>
                复制值
              </Button>
              <Button size="small" icon={<SwapOutlined />} onClick={() => setWrapPreview(prev => !prev)}>
                {wrapPreview ? '保持原格式' : '自动换行'}
              </Button>
              <Button size="small" icon={<FullscreenOutlined />} onClick={() => setPreviewOpen(true)}>
                全屏预览
              </Button>
            </Space>
          )}
          styles={{ body: { padding: 12, height: 'calc(100vh - 330px)', minHeight: 480, overflow: 'auto' } }}
          style={{ borderRadius: 14, overflow: 'hidden', minWidth: 0 }}
        >
          {expandedValue ? (
            <pre style={{
              margin: 0,
              padding: 18,
              minHeight: '100%',
              minWidth: wrapPreview ? 0 : 'max-content',
              fontSize: 12,
              fontFamily: "'SF Mono', 'Fira Code', monospace",
              lineHeight: 1.6,
              whiteSpace: wrapPreview ? 'pre-wrap' : 'pre',
              wordBreak: wrapPreview ? 'break-word' : 'normal',
              overflowWrap: wrapPreview ? 'anywhere' : 'normal',
              color: 'var(--text-primary)',
              background: 'var(--bg-subtle)',
              border: '1px solid var(--border-color)',
              borderRadius: 12,
            }}>
              {expandedValue.length > RAW_EVIDENCE_VALUE_PREVIEW_MAX_CHARS
                ? expandedValue.substring(0, RAW_EVIDENCE_VALUE_PREVIEW_MAX_CHARS) + '\n\n... (内容过长，已截断)'
                : expandedValue}
            </pre>
          ) : (
            <div style={{ padding: 24, textAlign: 'center', color: 'var(--text-muted)' }}>
              点击左侧路径查看对应值
            </div>
          )}
        </Card>
      </div>
      <Modal
        open={previewOpen}
        onCancel={() => setPreviewOpen(false)}
        footer={null}
        width="96vw"
        title={selectedPath || '值预览'}
        styles={{ body: { padding: 16 } }}
      >
        <pre style={{
          margin: 0,
          padding: 20,
          maxHeight: '82vh',
          overflow: 'auto',
          whiteSpace: wrapPreview ? 'pre-wrap' : 'pre',
          wordBreak: wrapPreview ? 'break-word' : 'normal',
          overflowWrap: wrapPreview ? 'anywhere' : 'normal',
          fontSize: 12,
          lineHeight: 1.6,
          fontFamily: "'SF Mono', 'Fira Code', monospace",
          background: 'var(--bg-subtle)',
          border: '1px solid var(--border-color)',
          borderRadius: 12,
        }}>
          {expandedValue || '选择左侧字段后查看原始值'}
        </pre>
      </Modal>
    </div>
  );
};

// ============ Sub-components ============

function PathResultItem({
  match,
  isSelected,
  onClick,
  onCopyPath,
}: {
  match: JsonPathMatch;
  isSelected: boolean;
  onClick: () => void;
  onCopyPath: () => void;
}) {
  const valuePreview = typeof match.value === 'object'
    ? JSON.stringify(match.value).substring(0, 60)
    : String(match.value).substring(0, 60);

  return (
    <div
      style={{
        padding: '8px 12px',
        borderBottom: '1px solid var(--border-color)',
        cursor: 'pointer',
        background: isSelected ? 'rgba(99, 102, 241, 0.06)' : 'transparent',
        transition: 'background 0.15s',
      }}
      onClick={onClick}
      onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = 'var(--bg-elevated)'; }}
      onMouseLeave={e => { if (!isSelected) e.currentTarget.style.background = 'transparent'; }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
        <span style={{
          fontSize: 12,
          fontFamily: "'SF Mono', monospace",
          color: '#6366f1',
          flex: 1,
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
        }}>
          {match.path}
        </span>
        <Tag style={{ margin: 0, fontSize: 10 }}>{match.type}</Tag>
        <Tooltip title="复制路径">
          <Button
            type="text"
            size="small"
            icon={<CopyOutlined />}
            onClick={e => { e.stopPropagation(); onCopyPath(); }}
            style={{ padding: '0 4px' }}
          />
        </Tooltip>
      </div>
      <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
        {valuePreview}
      </div>
    </div>
  );
}

function StructureItem({
  node,
  onClick,
  isSelected,
}: {
  node: StructureNode;
  onClick: () => void;
  isSelected: boolean;
}) {
  const indent = node.path ? (node.path.split('.').length - 1) * 16 : 0;

  return (
    <div
      style={{
        padding: '6px 12px',
        paddingLeft: 12 + indent,
        borderBottom: '1px solid var(--border-color)',
        cursor: 'pointer',
        background: isSelected ? 'rgba(99, 102, 241, 0.06)' : 'transparent',
        transition: 'background 0.15s',
      }}
      onClick={onClick}
      onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = 'var(--bg-elevated)'; }}
      onMouseLeave={e => { if (!isSelected) e.currentTarget.style.background = 'transparent'; }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
        <span style={{
          fontSize: 12,
          fontWeight: 500,
          color: 'var(--text-primary)',
        }}>
          {node.key || '(root)'}
        </span>
        <Tag style={{ margin: 0, fontSize: 10 }}>{node.type}</Tag>
        {node.childCount !== undefined && (
          <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
            ({node.childCount} items)
          </span>
        )}
      </div>
      <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
        {node.preview}
      </div>
    </div>
  );
}

export default RawEvidenceExplorer;
